s = "()[]{}"
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
ok = True
for ch in s:
    if ch in '([{':
        stack.append(ch)
    else:
        if not stack or stack[-1] != pairs[ch]:
            ok = False
            break
        stack.pop()
print(ok and len(stack) == 0)

s = "abaccdeff"
count = {}
for ch in s:
    count[ch] = count.get(ch, 0) + 1
ans = ''
for ch in s:
    if count[ch] == 1:
        ans = ch
        break
print(ans)
